public APIResponse<WrappedKeyResponse>
wrapKey(APIRequest<WrappedKeyRequest> req) {
// 1. API Address
String url = "http://172.30.16.243:48081/kms/api/v1/data/wrapkey";
// 2. Convert request object to JSON string
Gson gson = new Gson();
String jsonBody = gson.toJson(req);
HttpURLConnection connection = null;
BufferedReader reader = null;
try {
// 3. Create connection
URL postUrl = new URL(url);
connection = (HttpURLConnection) postUrl.openConnection();
connection.setRequestMethod("POST");
// 4. Set request headers
connection.setRequestProperty("Content-Type", "application/json;charset=UTF-8");
connection.setRequestProperty("Accept", "application/json");
// HX3-HMAC-SHA256, fixed
connection.setRequestProperty("Authorization", auth);
connection.setRequestProperty("msgId", "1111111111"); // Unique ID is required
connection.setDoOutput(true);
connection.setDoInput(true);
// 5. Set connection timeout
connection.setConnectTimeout(30000); // 30 seconds
connection.setReadTimeout(30000); // 30 seconds
// 6. Send request body
try (OutputStream os = connection.getOutputStream()) {
byte[] input = jsonBody.getBytes(StandardCharsets.UTF_8);
os.write(input, 0, input.length);
os.flush();
}
// 7. Get response code
int responseCode = connection.getResponseCode();
System.out.println("Response Code: " + responseCode);
// 8. Read response body
InputStream inputStream = null;

--- Page 2 ---
if (responseCode >= 200 && responseCode < 300) {
inputStream = connection.getInputStream();
} else {
inputStream = connection.getErrorStream();
}
reader = new BufferedReader(new InputStreamReader(inputStream,
StandardCharsets.UTF_8));
StringBuilder response = new StringBuilder();
String line;
while ((line = reader.readLine()) != null) {
response.append(line);
}
// 9. Parse response
String responseBody = response.toString();
System.out.println("Response Body: " + responseBody);
// Parse JSON response with Gson
return gson.fromJson(responseBody, APIResponse.class);
} catch (MalformedURLException e) {
throw new RuntimeException("Invalid URL format: " + url, e);
} catch (IOException e) {
throw new RuntimeException("Network request failed", e);
} catch (JsonSyntaxException e) {
throw new RuntimeException("Failed to parse response JSON", e);
} finally {
// 10. Clean up resources
if (reader != null) {
try {
reader.close();
} catch (IOException e) {
e.printStackTrace();
}
}
if (connection != null) {
connection.disconnect();
}
}
}
}

