--- Page 74 ---
5.1 RSAUtil.RSAInputStreamMethod
/**
* RSA encrypt/decrypt input stream
*
* @param inputStream Input stream (contains data to be processed)
* @param key Key string
* @param algorithm Algorithm name
* @param mode Operation mode (encrypt or decrypt)
* @return Processed byte array
* @throws NoSuchPaddingException, NoSuchAlgorithmException,
* InvalidKeySpecException, InvalidKeyException,
* IllegalBlockSizeException, BadPaddingException,
IOException
*/
public static byte[] RSAInputStream(InputStream inputStream, String
key, String algorithm, int mode)
throws NoSuchPaddingException, NoSuchAlgorithmException,
InvalidKeySpecException, InvalidKeyException,
IllegalBlockSizeException, BadPaddingException, IOException {
Cipher cipher;
switch (mode) {
case Cipher.ENCRYPT_MODE:
cipher = doEnkeyCipkey(key, algorithm); // Encryption
initialization
break;
default:
cipher = doDekeyCipkey(key, algorithm); // Decryption
initialization
}
int blockSize = cipher.getBlockSize();
if (inputStream == null) {
throw new IllegalArgumentException("Encryption source file
does not exist");
}
byte[] cache = new byte[blockSize];
byte[] main = new byte[0];
int nRead = 0;
while ((nRead = inputStream.read(cache)) != -1) {
byte[] encryptedSlice = cipher.doFinal(
Arrays.copyOfRange(cache, 0, nRead)
);
main = concatenateByteArrays(main, encryptedSlice);
}

--- Page 75 ---
inputStream.close();
return main;
}
6. Complete Example
6.1 Client Call Example
import java.nio.file.Files;
import java.nio.file.Paths;
public class ImportMaterialAsy {
public static void main(String[] args) {
importSingle();
}
public static void importSingle() {
try {
// 1. Initialize KMS client (for getting parameters)
KmsClient client =
CommonUtil.getKmsClient("/kms/api/v1/import/get/parameters");
// 2. Create import request object
ImpMaterialRequest impMaterialRequest = new
ImpMaterialRequest();
// 3. Set template alias
impMaterialRequest.setKeyId("templatealias/AES_ENCRYPT_DECRYPT");
// 4. Set validity period (0 indicates long-term
validity)
impMaterialRequest.setValidTo(0);
// 5. Set callback notification URL
impMaterialRequest.setNotifyUrl("http://172.30.11.17:8081/AMI/kmsview
back/basic/escrow");
// 6. Set wrapping algorithm
impMaterialRequest.setWrappingAlgorithm(WrappingAlgorithmEnum.RSAES_P
KCS1_V1_5.getValue());

--- Page 76 ---
// 7. Set wrapping key specification
impMaterialRequest.setWrappingKeySpec(KeySpecEnum.RSA_2048.getValue()
);
// 8. Set key material file input stream
impMaterialRequest.setFileInputStream(Files.newInputStream(Paths.get(
"C:\\XZ\\import1.csv")));
// 9. Create API request
APIRequest<ImpMaterialRequest> req = new APIRequest<>();
req.setReqParam(impMaterialRequest);
req.header.put("msgId", IdUtil.fastSimpleUUID()); //
Generate unique request ID
// 10. Execute async import
APIResponse<?> resp = client.importMaterialAsync(req);
// 11. Output response result
System.out.println(new Gson().toJson(resp));
} catch (Exception e) {
throw new RuntimeException("Failed to import key
material", e);
}
}
}
