/**
* Server-side async import logic implementation
*/
public APIResponse<?>
importMaterialAsync(APIRequest<ImpMaterialRequest> req) throws
HXCSDKException, FileNotFoundException {
// 1. Get request parameters
ImpMaterialRequest impMaterialRequest = req.getReqParam();
// 2. Build get parameters request
GetParametersRequest getParametersRequest = new
GetParametersRequest();
if (impMaterialRequest != null) {
getParametersRequest.setKeyId(impMaterialRequest.getKeyId());

