());
getParametersRequest.setWrappingKeySpec(impMaterialRequest.getWrappin
gKeySpec());
getParametersRequest.setWrappingAlgorithm(impMaterialRequest.getWrapp
ingAlgorithm());
}
// 3. Get import parameters (import token, public key, etc.)
APIRequest<GetParametersRequest> materialReq = new
APIRequest<>();
materialReq.setReqParam(getParametersRequest);
materialReq.header.put("msgId", req.header.get("msgId"));
materialReq.setSkipSign(false);
APIResponse<GetParametersResult> materialRep =
this.internalRequest(
materialReq,
"getParameters",
APIResponse.class
);
// 4. Process obtained parameters
if (materialRep != null) {
// Parse response data
Type objType = new TypeToken<GetParametersResult>()
{}.getType();
GetParametersResult getParametersResult =
gson.fromJson(gson.toJson(materialRep.getData()), objType);
String publicKey = getParametersResult.getPublicKey();
String importToken = getParametersResult.getImportToken();
byte[] encryptedFile = null;
// 5. If using RSA_2048 encryption, encrypt the file
if
("RSA_2048".equals(KeySpecEnum.getEnum(impMaterialRequest.getWrapping
KeySpec()).getType())) {
try {
// Encrypt file using RSA public key
encryptedFile = RSAUtil.RSAInputStream(
impMaterialRequest.getFileInputStream(),
publicKey,

