()).getName(),
Cipher.ENCRYPT_MODE
);
} catch (Exception e) {
e.printStackTrace();
throw new HXCSDKException(e.getMessage());
}
}
// 6. If there is an encrypted file, build multipart form
request
if (encryptedFile != null) {
Map<String, byte[]> multipartMap = new HashMap<>();
multipartMap.put("importToken", importToken.getBytes());
multipartMap.put("encryptedFile", encryptedFile);
multipartMap.put("validTo",
String.valueOf(impMaterialRequest.getValidTo()).getBytes());
if (!StrUtil.isEmpty(impMaterialRequest.getNotifyUrl()))
{
multipartMap.put("notifyUrl",
impMaterialRequest.getNotifyUrl().getBytes());
}
// 7. Create new API request
APIRequest newReq = new APIRequest();
newReq.setBinaryParams(new String[]{"importToken",
"encryptedFile"});
newReq.setMultipartParams((HashMap<String, byte[]>)
multipartMap);
newReq.header.put("msgId", IdUtil.fastSimpleUUID());
newReq.setSkipSign(false);
// 8. Set import path and execute async import
this.path = "/kms/api/v1/import/material/async";
return this.internalRequest(
newReq,
"importMaterialAsync",
APIResponse.class
);
}
// 9. If no encrypted file, return parameter retrieval result
return materialRep;

